function_info={
0:{'GatewayInvocationResponseMapper':'注入协议错误映射和 JSON 解析依赖。','toResponseEntity':'按失败类型、候选路由和上游响应生成 HTTP 响应，保留允许头，并检测成功状态中嵌入的上游错误。','nativeSuccessResponse':'在原生协议投影存在时使用投影正文和内容类型，否则保留上游正文。','embeddedUpstreamErrorResponse':'仅对成功状态的根级错误封套进行识别，并把上游错误转换为客户端协议响应。','embeddedErrorType':'从根级 error 对象或错误标记提取错误类型。','statusForEmbeddedError':'按上游错误类型选择认证、权限、限流、服务器或请求错误状态。','fallbackEmbeddedErrorMessage':'为缺少具体说明的嵌入式错误生成可读提示。','errorTypeForStatus':'按 HTTP 状态归类网关错误类型。','routeMapping':'从路由原因码和候选耗尽状态推导错误状态及类型。','embeddedErrorMapping':'结合嵌入式错误类型与消息中的配额信息映射错误状态。','protocolError':'将错误对象封装为指定协议的 HTTP JSON 响应。','extractUpstreamErrorMessage':'优先提取上游 JSON 错误消息，非 JSON 时使用整理后的正文。','readJson':'尝试解析上游 JSON 正文，已知解析失败返回空结果以保留兼容逻辑。','writeJson':'序列化错误对象，序列化失败时使用明确的服务器错误封套。','protocolErrorBody':'按 Messages 或 OpenAI 兼容格式生成错误对象。','firstText':'按字段顺序查找首个非空文本值。'},
1:{'GatewayStreamingResponseMapper':'注入网关服务、用量记录、流式映射及保活调度依赖。','toStreamingResponse':'设置流式响应头与请求标识，打开上游并转换流；记录成功或失败用量，在超时或断连后清理连接和调度任务。','streamInterrupted':'将流读取异常转换为网关流中断业务错误并保留原因。','keepAliveTicker':'使用共享守护调度线程按配置周期触发 SSE 保活。','writeSseHeaders':'设置 SSE 内容类型与禁止代理缓冲等响应头。','recordSuccess':'从转换上下文提取最终用量并记录成功调用。','recordFailure':'将流式失败及已收集用量写入调用计量。','writeProtocolError':'在协议适配的流式错误格式中写入失败信息。'},
2:{'ResponsesImageBridge':'注入图像调用端口、规划器、请求解析器、计量器和调用预算配置。','invoke':'解析图像请求并校验操作权限，执行规划，再按预算调用图像操作，组装并计量最终 Responses 响应或 SSE。','planResponses':'清理客户端载荷中的旧状态，构造规划请求并调用网关；规划失败时保留诊断信息并返回可终止结果。','invokeImagesOnce':'根据输入图像选择生成或编辑，定位支持该图像操作的路由并计量一次调用。','imageBody':'构建图像请求对象，写入模型、提示与经过覆盖后的工具参数。','binaryField':'将数据 URI 解析为二进制上传字段，外部图像 URL 按请求字段透传。','planningBody':'移除桥接状态和旧 Token 控制字段，生成图像规划专用 Responses 请求。','applyImagePlannerInstructions':'加入用于选择图像操作与整理提示的规划指令。','imageBodies':'按图像调用预算构建操作请求集合。','usageFrom':'从规划响应提取并规范化用量。','mergeUsage':'合并文本规划与图像调用的用量明细。','responseEnvelope':'构建包含图像结果、文本、状态和用量的 Responses 封套。','sseStream':'将最终封套拆成 Responses 生命周期、图像和文本 SSE 事件。','writeSse':'编码并写入单个 SSE 事件。','decodeImage':'解码输入 data URI 图像并生成上传文件元数据。'},
3:{'from':'读取 image_generation 工具及工具选择，规范化提示词、图像输入、模型、参数覆盖和最大调用次数，并校验 mask。','clampBudget':'将图像调用预算限制到允许范围并处理缺省值。','normalizedTools':'将支持的工具定义规范化以供图像工具识别。','rawTools':'从单工具或工具数组输入中提取工具节点。','containsImageTool':'判断工具定义中是否存在图像生成工具。','firstImageTool':'找到首个 image_generation 工具并保留其配置。','copied':'复制允许的图像工具覆盖字段而不修改原请求。','rejectRemoteMask':'拒绝作为普通 URL 提供的图像 mask，要求支持的内联数据。','normalizeOverrides':'将工具级参数名规范化为图像 API 支持的字段名。','text':'从输入文本与多模态文本块提取图像提示。','imageInputs':'收集可执行图像操作所需的多模态图像输入。','model':'从请求与工具覆盖配置选择图像模型。','addContentImages':'从多模态内容数组中收集图像 URL 或 data URI。','textFromContent':'将文本和多模态文本片段组合为提示字符串。'}
}
